  const marks = st.map((n, i) => `<g transform="translate(${rowX + i * (size + gapX)} ${rowY}) scale(${size / 100})">${state[n](C[roles.dark[n]])}${n === "lit" ? glowDot(C["gold-400"]) : ""}</g>`).join("");
