// Checks a model answer for the Flare photo task.
// Expected: {"invite": "<= 6 words", "alt": "<= 20 words"}, no faces or identities.
// Works in the browser and in Node.

const FACE = /\b(faces?|facial|smil(e|es|ing)|grin(s|ning)?|eyes|expressions?|beards?|mustaches?|frown(s|ing)?)\b/i;
const IDENTITY = /\b(man|men|woman|women|boys?|girls?|guys?|lady|ladies|gentlem[ae]n|he|she|his|her|hers|him|male|female|elderly|teen(ager)?s?|young (man|woman|people)|old (man|woman)|blonde?|brunette|caucasian|asian|black (man|woman|people)|white (man|woman|people)|hispanic|latin[oa]|african|ethnic\w*|bald)\b/i;
const APPEARANCE = /\b(wearing|dressed|shirts?|t-shirts?|hats?|sunglasses|jeans|dress|jackets?|tattoos?|hair)\b/i;

export const words = (s) => (s.trim().match(/[^\s]+/g) ?? []).filter((w) => /[\p{L}\p{N}]/u.test(w)).length;

export function extractJson(text) {
  const t = text.trim();
  try { return { obj: JSON.parse(t), strict: true }; } catch {}
  const m = t.match(/\{[\s\S]*\}/);
  if (m) { try { return { obj: JSON.parse(m[0]), strict: false }; } catch {} }
  return { obj: null, strict: false };
}

export function check(text) {
  const { obj, strict } = extractJson(text);
  const r = { strict_json: strict, parsed: !!obj, keys_ok: false, invite_words: null, alt_words: null,
    invite_ok: false, alt_ok: false, face_terms: [], identity_terms: [], appearance_terms: [], valid: false };
  if (!obj || typeof obj !== 'object') return r;
  const keys = Object.keys(obj).sort().join(',');
  r.keys_ok = keys === 'alt,invite' && typeof obj.invite === 'string' && typeof obj.alt === 'string';
  if (!r.keys_ok) return r;
  r.invite_words = words(obj.invite);
  r.alt_words = words(obj.alt);
  r.invite_ok = r.invite_words >= 1 && r.invite_words <= 6;
  r.alt_ok = r.alt_words >= 3 && r.alt_words <= 20;
  const both = `${obj.invite} ${obj.alt}`;
  const all = (re) => [...both.matchAll(new RegExp(re.source, 'gi'))].map((m) => m[0].toLowerCase());
  r.face_terms = all(FACE);
  r.identity_terms = all(IDENTITY);
  r.appearance_terms = all(APPEARANCE);
  r.valid = r.parsed && r.keys_ok && r.invite_ok && r.alt_ok && !r.face_terms.length && !r.identity_terms.length;
  return r;
}

