// Deterministic guard the app should run on every model answer before showing or speaking it.
// Returns {invite, alt, repaired: [...]} or null if the answer cannot be used (fall back to a template).
export function enforce(text) {
  const { obj } = extractJson(text);
  if (!obj || typeof obj.invite !== 'string' || typeof obj.alt !== 'string') return null;
