// Hub relay (ADR-0006). The Mac hub opens an outbound WebSocket to /hub with a shared
// secret; the server sends photo jobs over it and waits for the JSON result.
// The photo exists only in memory on both ends and is never written to disk or logs.
import { randomUUID, timingSafeEqual } from "node:crypto";
import type { IncomingMessage } from "node:http";
import { FromHub, HUB_PROTOCOL, type JobHeaderT, type JobResultT } from "@flare/shared";
import type { WebSocket } from "ws";
import { log } from "../log.ts";

type Pending = { resolve: (r: JobResultT | null) => void; timer: NodeJS.Timeout };

export function secretMatches(given: string | undefined, expected: string): boolean {
  if (!expected || !given) return false;
  const a = Buffer.from(given);
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

export function bearer(req: IncomingMessage): string | undefined {
  const h = req.headers.authorization;
  return h?.startsWith("Bearer ") ? h.slice(7) : undefined;
}

export class HubRelay {
  private socket: WebSocket | null = null;
  private model = "";
  private ready = false;
  private pending = new Map<string, Pending>();
  private pinger: NodeJS.Timeout | null = null;

  private readonly timeoutMs: number;

  constructor(timeoutMs: number) {
    this.timeoutMs = timeoutMs;
  }

  get status(): "connected" | "absent" {
    return this.socket && this.ready ? "connected" : "absent";
  }

  attach(ws: WebSocket): void {
    if (this.socket) {
      log.info({ event: "hub.replaced" }, "hub replaced");
      this.socket.close(4000, "replaced");
    }
    this.socket = ws;
    this.ready = false;
    ws.on("message", (data, isBinary) => {
      if (isBinary) return; // the hub never sends binary
      let msg: unknown;
      try {
        msg = JSON.parse(String(data));
      } catch {
        return;
      }
      const parsed = FromHub.safeParse(msg);
      if (!parsed.success) return;
      const m = parsed.data;
      if (m.type === "hello") {
        this.model = m.model;
        this.ready = m.ready;
        log.info({ event: "hub.hello", model: m.model, ready: m.ready }, "hub connected");
      } else if (m.type === "result") {
        const p = this.pending.get(m.id);
        if (!p) return;
        clearTimeout(p.timer);
        this.pending.delete(m.id);
        p.resolve(m);
      }
    });
    ws.on("close", () => {
      if (this.socket === ws) {
        this.socket = null;
        this.ready = false;
        log.info({ event: "hub.closed" }, "hub disconnected");
      }
    });
    if (this.pinger) clearInterval(this.pinger);
    this.pinger = setInterval(() => this.socket?.send(JSON.stringify({ type: "ping", t: Date.now() })), 20_000);
    this.pinger.unref();
// Hub relay protocol (docs/architecture/contracts/asyncapi.yaml, channel /hub).
// The Mac hub opens an outbound WebSocket to the server; the server sends jobs.
// Text frames carry JSON control messages; a photo job is one text frame (job header)
// followed by one binary frame (the 768 px JPEG). Nothing on the Mac is exposed (ADR-0006).
import { z } from "zod";

export const HUB_PROTOCOL = "flare-hub.v1";

export const HelloFromHub = z.object({
  type: z.literal("hello"),
  protocol: z.literal(HUB_PROTOCOL),
  model: z.string().min(1),
  ready: z.boolean(),
});

export const JobHeader = z.object({
  type: z.literal("job"),
  id: z.string().uuid(),
  kind: z.literal("photo-draft"),
  bytes: z.number().int().positive().max(2_000_000),
  mime: z.literal("image/jpeg"),
});

export const JobResult = z.object({
  type: z.literal("result"),
  id: z.string().uuid(),
  ok: z.boolean(),
  draft: z.object({ invite: z.string().min(1), alt: z.string().min(1) }).optional(),
  error: z.enum(["model_unavailable", "unusable_answer", "timeout", "bad_image"]).optional(),
  ms: z.number().int().nonnegative(),
  model: z.string(),
});

export const Ping = z.object({ type: z.literal("ping"), t: z.number() });
export const Pong = z.object({ type: z.literal("pong"), t: z.number() });

export const FromHub = z.discriminatedUnion("type", [HelloFromHub, JobResult, Pong]);
export const ToHub = z.discriminatedUnion("type", [JobHeader, Ping]);

export type JobHeaderT = z.infer<typeof JobHeader>;
export type JobResultT = z.infer<typeof JobResult>;
export type FromHubT = z.infer<typeof FromHub>;
export type ToHubT = z.infer<typeof ToHub>;
// HTTP payloads shared by web and server (docs/architecture/contracts/openapi.yaml).
import { z } from "zod";

export const DraftResponse = z.object({
  invite: z.string().min(1),
  alt: z.string(),
  tier: z.enum(["hub", "rules"]),
  ms: z.number().int().nonnegative(),
});
export type DraftResponseT = z.infer<typeof DraftResponse>;

export const Health = z.object({
  ok: z.boolean(),
  version: z.string(),
  hub: z.enum(["connected", "absent"]),
  db: z.enum(["ok", "down", "not_configured"]),
});
export type HealthT = z.infer<typeof Health>;

export const MAX_PHOTO_BYTES = 1_500_000;

