// Hub side of the relay (ADR-0006, contracts/asyncapi.yaml). Opens one outbound
// WebSocket to the server, answers pings, runs one photo job at a time, reconnects
// with exponential backoff. Imports no filesystem module: photos never touch disk.
import { HUB_PROTOCOL, JobHeader, type JobResultT, Ping, ToHub } from "@flare/shared";
import WebSocket from "ws";
import { draftFromPhoto, isModelReady, type OllamaConfig } from "./ollama.ts";

export type HubOptions = {
  serverUrl: string;
  secret: string;
  ollama: OllamaConfig;
  onLog?: (e: Record<string, unknown>) => void;
};

export function startHub(opts: HubOptions): { stop: () => void } {
  const say = opts.onLog ?? (() => {});
  let ws: WebSocket | null = null;
  let stopped = false;
  let delay = 1000;
  let waitingFor: { id: string; bytes: number } | null = null;

  const connect = () => {
    if (stopped) return;
    ws = new WebSocket(`${opts.serverUrl.replace(/\/$/, "")}/hub`, {
      headers: { authorization: `Bearer ${opts.secret}` },
    });
    ws.on("open", async () => {
      delay = 1000;
      const ready = await isModelReady(opts.ollama);
      ws?.send(JSON.stringify({ type: "hello", protocol: HUB_PROTOCOL, model: opts.ollama.model, ready }));
      say({ event: "connected", ready });
    });
    ws.on("message", async (data, isBinary) => {
      if (!isBinary) {
        let raw: unknown;
        try {
          raw = JSON.parse(String(data));
        } catch {
          return;
        }
        const m = ToHub.safeParse(raw);
        if (!m.success) return;
        if (m.data.type === "ping") {
          const p = Ping.parse(m.data);
          ws?.send(JSON.stringify({ type: "pong", t: p.t }));
        } else {
          const h = JobHeader.parse(m.data);
          waitingFor = { id: h.id, bytes: h.bytes };
        }
        return;
      }
      if (!waitingFor) return;
      const job = waitingFor;
      waitingFor = null;
      const photo = data as Buffer;
      const t = performance.now();
      let result: JobResultT;
      try {
        if (photo.length !== job.bytes || photo[0] !== 0xff || photo[1] !== 0xd8)
          throw Object.assign(new Error("bad image"), { code: "bad_image" });
        const d = await draftFromPhoto(opts.ollama, photo);
        result = d
          ? {
              type: "result",
              id: job.id,
              ok: true,
              draft: { invite: d.invite, alt: d.alt },
              ms: Math.round(performance.now() - t),
              model: opts.ollama.model,
            }
          : {
              type: "result",
              id: job.id,
              ok: false,
              error: "unusable_answer",
              ms: Math.round(performance.now() - t),
              model: opts.ollama.model,
            };
      } catch (e) {
        const code = (e as { code?: string }).code === "bad_image" ? "bad_image" : "model_unavailable";
        result = {
          type: "result",
          id: job.id,
          ok: false,
          error: code,
          ms: Math.round(performance.now() - t),
          model: opts.ollama.model,
        };
      } finally {
        photo.fill(0); // clear the photo bytes as soon as the job ends
      }
      ws?.send(JSON.stringify(result));
      say({ event: "job", ok: result.ok, ms: result.ms });
    });
    ws.on("close", (code) => {
      say({ event: "closed", code });
      if (!stopped) setTimeout(connect, delay);
      delay = Math.min(delay * 2, 30_000);
    });
    ws.on("error", () => {}); // close follows; backoff handles it
  };
  connect();
  return {
    stop: () => {
      stopped = true;
      ws?.close();
    },
  };
}

// Calls Ollama for the photo task with the settings the lab proved (report 02):
// GGUF tag, think:false, prompt-only (no format), temperature 0, num_predict 128.
// The image is passed as base64 in the request body and lives only in memory.
import { type Draft, enforce, SYSTEM_PROMPT, USER_PROMPT } from "@flare/shared";

export type OllamaConfig = { url: string; model: string; timeoutMs: number };

export async function chat(cfg: OllamaConfig, imageBase64: string | null, signal?: AbortSignal): Promise<string> {
  const body = {
    model: cfg.model,
    stream: false,
    think: false,
    keep_alive: "30m",
    messages: [
      { role: "system", content: SYSTEM_PROMPT },
      imageBase64
        ? { role: "user", content: USER_PROMPT, images: [imageBase64] }
        : { role: "user", content: "Reply with {}" },
    ],
    options: { temperature: 0, seed: 42, num_predict: 128 },
  };
  const res = await fetch(`${cfg.url}/api/chat`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
    signal: signal ?? AbortSignal.timeout(cfg.timeoutMs),
  });
  if (!res.ok) throw new Error(`ollama ${res.status}`);
  const json = (await res.json()) as { message?: { content?: string } };
  return json.message?.content ?? "";
}

/** One photo in, one guarded draft out. Retries once on an unusable answer (report 02). */
export async function draftFromPhoto(cfg: OllamaConfig, jpeg: Uint8Array): Promise<Draft | null> {
  const b64 = Buffer.from(jpeg).toString("base64");
  for (let attempt = 0; attempt < 2; attempt++) {
    const text = await chat(cfg, b64);
    const d = enforce(text);
    if (d) return d;
  }
  return null;
}

export async function isModelReady(cfg: OllamaConfig): Promise<boolean> {
  try {
    const res = await fetch(`${cfg.url}/api/tags`, { signal: AbortSignal.timeout(3000) });
    const tags = (await res.json()) as { models?: { name: string }[] };
    return !!tags.models?.some((m) => m.name === cfg.model);
  } catch {
    return false;
  }
}
