let lastReset = 0;
await run("reset every 10 s", (p, t) => {
  if (t - lastReset >= 10_000) {
    lastReset = t;
    p.reset();
  }
});
lastReset = 0;
let holed = false;
await run("silent drop (half-open) at 10 s", (p, t) => {
  if (!holed && t >= 10_000) {
    holed = true;
    p.blackhole();
  }
});
holed = false;
ollama.close();
if (OUT) fs.writeFileSync(OUT, JSON.stringify(results, null, 2));
process.exit(0);
