      hub.stop();
      wss.close();
    };
    await new Promise((r) => setTimeout(r, 1200));
    expect(at.length).toBeGreaterThanOrEqual(2);
    expect((at[1] ?? 0) - (at[0] ?? 0)).toBeLessThan(800); // 50 ms + 250 ms first retry
  });
});
