});
const Amenity = z.object({ count: z.number().int().min(0), nearest_m: z.number().int().min(0).nullable() });

export const SealedGathering = z.object({
  v: z.literal(1),
  host_name: z.string().min(1).max(40),
  invite: z.string().min(1).max(80),
