    { href: "/privacy/", label: t("site.nav.privacy") },
    { href: "/accessibility/", label: t("site.nav.access") },
    { href: "/run/", label: t("site.nav.run") },
  ];
  const current = (href: string) => (page.url.pathname === href ? "page" : undefined);
</script>

