async function sendFlare(page: Page, quorum: string, tag: string | null): Promise<string> {
  await page.goto(U + "/app/");
  await page.getByRole("button", { name: "Take the photo" }).click({ timeout: 15_000 });
  await page.getByRole("button", { name: /Use these|Use mine/ }).waitFor({ timeout: 15_000 });
  const where = page.getByLabel("Where are you?");
  if (await where.isVisible().catch(() => false)) { await where.fill("Ford Woods Park, by the pond"); await page.getByRole("button", { name: "Not now" }).click(); }
  const use = page.getByRole("button", { name: "Use these" });
  if (await use.waitFor({ timeout: 15_000 }).then(() => true, () => false)) { if (tag) await shot(page, \`\${tag}-words\`); await use.click(); }
  else { await page.getByRole("textbox").first().fill("Pond walk, come sit"); await page.getByRole("button", { name: "Use mine" }).click(); }
  const name = page.getByLabel("Your first name");
  if (await name.isVisible().catch(() => false)) await name.fill("Fuego");
  await page.getByRole("radio", { name: quorum, exact: true }).check().catch(() => {});
  if (tag) await shot(page, \`\${tag}-send\`);
  await page.getByRole("button", { name: "Send it" }).click();
  await page.getByRole("heading", { name: "Sent." }).waitFor({ timeout: 15_000 });
  if (tag) await shot(page, \`\${tag}-sent\`);
  await page.getByRole("button", { name: "Copy as text" }).click();
  const clip = await page.evaluate(() => navigator.clipboard.readText());
  await page.getByRole("button", { name: "Pocket it" }).click();
  return clip.match(/(\/g\/[0-9a-f-]{36}\/#k=[A-Za-z0-9_-]{43})/)?.[1] ?? "";
}
