// The compass guide (SRS-CMP-1 to -3; device check fix, Sun 2026-10-11). Pure: raw sensor
// samples in, a steady direction out. Used by the app's Find them screen and, as a generated
// plain-JS copy (static/check/guide.js, `npm run gen:guide`), by the device-check compass page.
// No imports, so the copy needs nothing else.
//
// What it fixes from the iPhone 16 Pro Max run (iOS 26.6.1, 20 to 50 events/s, compass
// accuracy about 14°, GPS 2.5 to 3 m):
// - Heading is smoothed on the circle (unit vectors, time-based), so 359° and 1° average to 0°.
// - The screen's rotation is added, so the arrow points right in landscape too.
// - Tilted past 65° (phone held up like a camera), the magnetometer heading is unreliable:
//   the last good heading is kept and the hint says to hold the phone flat.
// - Walking at 1 m/s or more, the GPS course (direction of travel) replaces the compass.
// - The bearing to the target only updates while the distance is more than twice the fix's
//   accuracy; closer than that, the direction is noise, so the guide says you're close.
// - Worse fixes (over 50 m) and dropped fixes keep the last good bearing.
// - "Facing" locks at 15° and lets go at 25°, so a shaky hand doesn't flicker it.
// - A poor compass (accuracy over 25°, or -1 = uncalibrated) asks for a figure 8.

export type LatLon = { lat: number; lon: number };
export type HeadingSample = {
  t: number;
  /** webkitCompassHeading (iOS), or 360 - alpha from deviceorientationabsolute. */
  heading: number;
  /** webkitCompassAccuracy in degrees; -1 means uncalibrated. */
  accuracy?: number | null;
  /** Front-back tilt: 0 flat, 90 upright. */
  beta?: number | null;
  /** Left-right tilt. */
  gamma?: number | null;
  /** screen.orientation.angle: 0 portrait, 90 or 270 landscape. */
  screen?: number;
};
export type Fix = LatLon & { t: number; accuracy: number; speed?: number | null; course?: number | null };
export type Hint = "flat" | "figure8" | null;
export type GuideState = {
  heading: number | null;
  source: "compass" | "course" | null;
  distance_m: number | null;
  /** Absolute bearing to the target, held while too close or without a good fix. */
  bearing_deg: number | null;
  /** Bearing relative to where the phone points, -180 to 180 (negative = left). */
  rel_deg: number | null;
  facing: boolean;
  /** Closer than twice the fix's accuracy: no direction, just "you're close". */
  near: boolean;
  hint: Hint;
  accuracy_m: number | null;
  /** No fix for 10 s: the distance and bearing are the last good ones. */
  stale: boolean;
};

export const SMOOTH_MS = 250;
export const TILT_MAX_DEG = 65;
export const POOR_COMPASS_DEG = 25;
export const WALK_ON_MPS = 1.0;
export const WALK_OFF_MPS = 0.6;
export const MAX_FIX_M = 50;
export const NEAR_FACTOR = 2;
export const FACE_IN_DEG = 15;
export const FACE_OUT_DEG = 25;
export const STALE_MS = 10_000;

const RAD = Math.PI / 180;
const norm = (d: number) => ((d % 360) + 360) % 360;
/** Signed difference b - a, -180 to 180. */
export const angleDiff = (a: number, b: number) => ((((b - a) % 360) + 540) % 360) - 180;

export function distanceM(a: LatLon, b: LatLon): number {
  const h =
    Math.sin(((b.lat - a.lat) * RAD) / 2) ** 2 +
    Math.cos(a.lat * RAD) * Math.cos(b.lat * RAD) * Math.sin(((b.lon - a.lon) * RAD) / 2) ** 2;
  return 2 * 6_371_000 * Math.asin(Math.min(1, Math.sqrt(h)));
}
export function bearingDeg(a: LatLon, b: LatLon): number {
  const y = Math.sin((b.lon - a.lon) * RAD) * Math.cos(b.lat * RAD);
  const x =
    Math.cos(a.lat * RAD) * Math.sin(b.lat * RAD) - Math.sin(a.lat * RAD) * Math.cos(b.lat * RAD) * Math.cos((b.lon - a.lon) * RAD);
  return norm(Math.atan2(y, x) / RAD);
}

/** Time-based circular low-pass: averages unit vectors, so it never takes the long way round. */
export function circularSmooth(prev: number | null, next: number, dtMs: number, tauMs = SMOOTH_MS): number {
  if (prev === null || !Number.isFinite(dtMs) || dtMs <= 0) return norm(next);
  const k = 1 - Math.exp(-dtMs / tauMs);
  const x = (1 - k) * Math.cos(prev * RAD) + k * Math.cos(next * RAD);
  const y = (1 - k) * Math.sin(prev * RAD) + k * Math.sin(next * RAD);
  return norm(Math.atan2(y, x) / RAD);
}

export type Guide = {
  orientation(s: HeadingSample): GuideState;
  position(f: Fix): GuideState;
  /** Advance time with no new fix (marks stale fixes). */
  tick(t: number): GuideState;
  setTarget(target: LatLon | null): GuideState;
  state(): GuideState;
};

export function createGuide(initialTarget: LatLon | null = null): Guide {
  let target = initialTarget;
  let compass: number | null = null;
  let compassAt = -Infinity;
  let course: number | null = null;
  let courseAt = -Infinity;
  let walking = false;
  let tilted = false;
  let poor = false;
  let fix: Fix | null = null;
  let lastFixAt = -Infinity;
  let now = 0;
  let s: GuideState = {
    heading: null,
    source: null,
    distance_m: null,
    bearing_deg: null,
    rel_deg: null,
    facing: false,
    near: false,
    hint: null,
    accuracy_m: null,
    stale: false,
  };

  const recompute = (): GuideState => {
    const source: GuideState["source"] = walking && course !== null ? "course" : compass !== null ? "compass" : null;
    const heading = source === "course" ? course : compass;
    let { distance_m, bearing_deg } = s;
    let near = s.near;
    if (fix && target) {
      distance_m = distanceM(fix, target);
      near = distance_m <= NEAR_FACTOR * fix.accuracy;
      if (!near) bearing_deg = bearingDeg(fix, target); // else keep the last good bearing
    }
    const rel = heading === null || bearing_deg === null || near ? null : angleDiff(heading, bearing_deg);
    const facing = rel !== null && Math.abs(rel) <= (s.facing ? FACE_OUT_DEG : FACE_IN_DEG);
    const hint: Hint = source === "course" ? null : tilted ? "flat" : poor ? "figure8" : null;
    s = {
      heading,
      source,
      distance_m,
      bearing_deg,
      rel_deg: rel,
      facing,
      near,
      hint,
      accuracy_m: fix?.accuracy ?? null,
      stale: now - lastFixAt > STALE_MS,
    };
    return s;
  };

  return {
    orientation(x) {
      now = Math.max(now, x.t);
      const beta = Math.abs(x.beta ?? 0);
      const gamma = Math.abs(x.gamma ?? 0);
      tilted = beta > TILT_MAX_DEG || gamma > TILT_MAX_DEG;
      poor = typeof x.accuracy === "number" && (x.accuracy < 0 || x.accuracy > POOR_COMPASS_DEG);
      if (!tilted && Number.isFinite(x.heading)) {
        const h = norm(x.heading + (x.screen ?? 0));
        compass = circularSmooth(compass, h, x.t - compassAt);
        compassAt = x.t;
      }
      return recompute();
    },
    position(f) {
      now = Math.max(now, f.t);
      const speed = f.speed ?? null;
      if (speed !== null && Number.isFinite(speed)) walking = walking ? speed >= WALK_OFF_MPS : speed >= WALK_ON_MPS;
      if (walking && typeof f.course === "number" && Number.isFinite(f.course) && f.course >= 0) {
        course = circularSmooth(course, f.course, f.t - courseAt, 1000);
        courseAt = f.t;
      }
      if (f.accuracy <= MAX_FIX_M || !fix) {
        fix = f;
        lastFixAt = f.t;
      }
      return recompute();
    },
    tick(t) {
      now = Math.max(now, t);
      return recompute();
    },
    setTarget(next) {
      target = next;
      s = { ...s, bearing_deg: null, distance_m: null, near: false, facing: false };
      return recompute();
    },
    state: () => s,
  };
}

/** The arrow's on-screen angle without the long-way spin: follow the shortest turn. */
export function unwrapAngle(prevShown: number, next: number): number {
  return prevShown + angleDiff(prevShown, next);
}

// Compass guide replays (device check, iPhone 16 Pro Max, iOS 26.6.1). The device report held
// summary stats, not raw streams, so these streams are generated to match them: headings at
// 50 Hz with about 14° of noise, GPS fixes once a second at 2.5 to 3 m. The check page now
// records raw streams (relative metres only), so the next run can be replayed as is.
import { describe, expect, it } from "vitest";
import { angleDiff, createGuide, type Fix, unwrapAngle } from "../../src/lib/compass/guide.ts";

// Deterministic noise.
function rng(seed: number) {
  let x = seed;
  return () => {
    x = (x * 1664525 + 1013904223) % 2 ** 32;
    return x / 2 ** 32;
  };
}
const gauss = (r: () => number) => Math.sqrt(-2 * Math.log(r() || 1e-9)) * Math.cos(2 * Math.PI * r());

const TARGET = { lat: 42.3196, lon: -83.2129 };
/** A point `north` and `east` metres from the target. */
const at = (north: number, east: number) => ({
  lat: TARGET.lat + north / 111_320,
  lon: TARGET.lon + east / (111_320 * Math.cos((TARGET.lat * Math.PI) / 180)),
});

describe("compass guide replay", () => {
  it("standing still, noisy heading around north: steady, no spin through 0/360", () => {
    const g = createGuide(TARGET);
    const r = rng(1);
    g.position({ ...at(30, 0), t: 0, accuracy: 3, speed: 0 }); // 30 m north of the target
    const seen: number[] = [];
    for (let i = 0; i < 500; i++) {
      const s = g.orientation({ t: i * 20, heading: (360 + 180 + 14 * gauss(r)) % 360, accuracy: 14, beta: 10 });
      if (i > 50) seen.push(s.heading as number);
    }
    // The person faces south (180), toward the target: steady within a few degrees.
    const worst = Math.max(...seen.map((h) => Math.abs(angleDiff(180, h))));
    expect(worst).toBeLessThan(8);
    expect(g.state().facing).toBe(true);
    // Around north the raw values wrap 350..10; the smoothed heading stays near 0, never near 180.
    const n = createGuide(TARGET);
    for (let i = 0; i < 300; i++) n.orientation({ t: i * 20, heading: (360 + 14 * gauss(r)) % 360, accuracy: 14 });
    expect(Math.abs(angleDiff(0, n.state().heading as number))).toBeLessThan(8);
  });

  it("facing locks at 15° and lets go only past 25° (a shaky hand doesn't flicker it)", () => {
    const g = createGuide(TARGET);
    g.position({ ...at(30, 0), t: 0, accuracy: 3 });
    let flips = 0;
    let was = false;
    for (let i = 0; i < 400; i++) {
      // Wobbling between 160° and 200° (rel -20..+20) after first pointing straight at it.
      const h = i < 50 ? 180 : 180 + 20 * Math.sin(i / 7);
      const s = g.orientation({ t: i * 20, heading: h, accuracy: 14 });
      if (s.facing !== was) flips++;
      was = s.facing;
    }
    expect(flips).toBe(1); // locked once, never let go
  });

  it("walking away north at 1.3 m/s: GPS course replaces the compass, target reads behind", () => {
    const g = createGuide(TARGET);
    const r = rng(2);
    let s = g.state();
    for (let sec = 0; sec <= 30; sec++) {
      const north = 5 + 1.3 * sec;
      const fix: Fix = { ...at(north + 3 * gauss(r) * 0.5, 3 * gauss(r) * 0.5), t: sec * 1000, accuracy: 3, speed: 1.3, course: (360 + 4 * gauss(r)) % 360 };
      s = g.position(fix);
      // The compass meanwhile is swinging (phone in a hand, swinging while walking).
      for (let k = 0; k < 20; k++) g.orientation({ t: sec * 1000 + k * 50, heading: (360 + 60 * Math.sin(k)) % 360, accuracy: 14 });
      s = g.state();
    }
    expect(s.source).toBe("course");
    expect(Math.abs(angleDiff(180, s.bearing_deg as number))).toBeLessThan(10);
    expect(Math.abs(s.rel_deg as number)).toBeGreaterThan(160); // behind you
    // Stops: below 0.6 m/s it goes back to the compass.
    s = g.position({ ...at(44, 0), t: 32_000, accuracy: 3, speed: 0.2, course: -1 });
    g.orientation({ t: 32_100, heading: 180, accuracy: 14 });
    expect(g.state().source).toBe("compass");
  });

  it("closer than twice the accuracy: says near, keeps the last good bearing, no false direction", () => {
    const g = createGuide(TARGET);
    g.position({ ...at(20, 0), t: 0, accuracy: 3 });
    g.orientation({ t: 10, heading: 180, accuracy: 14 });
    const far = g.state();
    expect(far.near).toBe(false);
    expect(Math.round(far.bearing_deg as number)).toBe(180);
    // 4 m away with a 3 m fix: near. The jittery fix on the other side must not flip the bearing.
    const s = g.position({ ...at(-4, 1), t: 1000, accuracy: 3 });
    expect(s.near).toBe(true);
    expect(s.rel_deg).toBeNull();
    expect(Math.round(s.bearing_deg as number)).toBe(180);
  });

  it("a bad or dropped fix keeps the last good bearing and marks it stale after 10 s", () => {
    const g = createGuide(TARGET);
    g.position({ ...at(50, 0), t: 0, accuracy: 3 });
    const good = g.state().bearing_deg;
    g.position({ ...at(0, 300), t: 1000, accuracy: 120 }); // a 120 m fix: ignored
    expect(g.state().bearing_deg).toBe(good);
    expect(Math.round(g.state().distance_m as number)).toBe(50);
    expect(g.tick(5000).stale).toBe(false);
    expect(g.tick(11_000).stale).toBe(true);
    expect(g.state().bearing_deg).toBe(good);
  });

  it("held upright like a camera: keeps the last heading and asks to hold it flat", () => {
    const g = createGuide(TARGET);
    g.position({ ...at(30, 0), t: 0, accuracy: 3 });
    g.orientation({ t: 0, heading: 180, accuracy: 14, beta: 20 });
    const s = g.orientation({ t: 20, heading: 0, accuracy: 14, beta: 85 }); // the flip iOS gives upright
    expect(s.hint).toBe("flat");
    expect(Math.round(s.heading as number)).toBe(180);
    expect(g.orientation({ t: 40, heading: 181, accuracy: 14, beta: 15 }).hint).toBeNull();
  });

  it("an uncalibrated or poor compass asks for a figure 8", () => {
    const g = createGuide(TARGET);
    expect(g.orientation({ t: 0, heading: 90, accuracy: -1 }).hint).toBe("figure8");
    expect(g.orientation({ t: 20, heading: 90, accuracy: 40 }).hint).toBe("figure8");
    expect(g.orientation({ t: 40, heading: 90, accuracy: 12 }).hint).toBeNull();
  });

  it("landscape: adds the screen's rotation so the arrow still points the right way", () => {
    const g = createGuide(TARGET);
    g.position({ ...at(30, 0), t: 0, accuracy: 3 });
    const s = g.orientation({ t: 0, heading: 90, accuracy: 14, screen: 90 }); // device top east, screen up south
    expect(Math.round(s.heading as number)).toBe(180);
    expect(s.facing).toBe(true);
  });

  it("the arrow follows the short way round: 170° to -170° is a 20° turn, not 340°", () => {
    expect(unwrapAngle(170, -170)).toBe(190);
    expect(unwrapAngle(-170, 170)).toBe(-190);
    expect(unwrapAngle(10, 350)).toBe(-10);
  });
});

