// plus a manifest the app reads. Credits: docs/credits/photos.md. Usage: npm run scenic
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SRC = path.join(ROOT, "scripts/scenic-src");
const OUT = path.join(ROOT, "apps/web/static/scenic");
const WIDTHS = [640, 1280] as const;
const credits = JSON.parse(fs.readFileSync(path.join(SRC, "credits.json"), "utf8")) as {
  slug: string;
  title: string;
  author: string;
  license: string;
  source: string;
}[];
fs.mkdirSync(OUT, { recursive: true });
const manifest = [];
for (const c of credits) {
  const input = path.join(SRC, `${c.slug}.jpg`);
  for (const w of WIDTHS) {
    const img = sharp(input).resize({ width: w, withoutEnlargement: true });
    await img.clone().avif({ quality: 50, effort: 6 }).toFile(path.join(OUT, `${c.slug}-${w}.avif`));
    await img.clone().webp({ quality: 72 }).toFile(path.join(OUT, `${c.slug}-${w}.webp`));
  }
  const meta = await sharp(input).metadata();
  manifest.push({ slug: c.slug, author: c.author, license: c.license, source: c.source, ratio: (meta.width ?? 16) / (meta.height ?? 9) });
}
fs.writeFileSync(path.join(OUT, "manifest.json"), `${JSON.stringify(manifest, null, 1)}\n`);
const size = fs.readdirSync(OUT).reduce((a, f) => a + fs.statSync(path.join(OUT, f)).size, 0);
console.info(`scenic: ${credits.length} photos, ${WIDTHS.length * 2} files each, ${Math.round(size / 1024)} KB total`);
EOF
