const OR_ALTERNATIVE = /\bor\b(?!\s+(less|smaller|shorter|fewer|under|below|more|bigger|longer|nothing|bust)\b)/i;
const NOT_NAMES = new Set([
  "i",
  "it",
  "its",
  "the",
  "we",
  "you",
  "they",
  "my",
  "me",
  "possible",
  "needed",
  "so",
  "that",
  "there",
