  return r.rules
    .map((x) => (x.type === "with" ? `with=${x.member_id}` : "at" in x ? `${x.type}=${local(x.at)}` : x.type))
    .sort()
    .join("|");
};

const DELAYS = ["10min", "10mins", "10m", "10 min", "10 minutes", "in 10", "after 10 min", "give me 10", "can come in 10 min"];

